<script>
  let input = '';
  let media = [];
  let selected = 0;
  let loading = false;
  let error = '';
  let status = '';
  let copied = false;
  let stage = '';

  const isInstagramUrl = value => { try { const u = new URL(value); return /(^|\.)instagram\.com$/i.test(u.hostname) && /^\/(p|reel|reels|tv)\//i.test(u.pathname); } catch { return false; } };
  const isVideoUrl = value => { try { const u = new URL(value); return /(^|\.)instagram\.com$/i.test(u.hostname) && /^\/(reel|reels|tv)\//i.test(u.pathname); } catch { return false; } };
  const normalizeUrl = value => String(value || '').replace(/\\u0026/g,'&').replace(/\\u002F/gi,'/').replace(/\\\//g,'/').replace(/&amp;/g,'&').replace(/\\u003D/g,'=').replace(/\\u003F/g,'?').replace(/\\u0025/gi,'%');
  const validUrl = value => { try { const u = new URL(normalizeUrl(value)); return /(^|\.)cdninstagram\.com$|(^|\.)fbcdn\.net$|(^|\.)fbsbx\.com$/i.test(u.hostname); } catch { return false; } };
  const area = x => (x.width || 0) * (x.height || 0);
  const resolution = (w,h) => w && h ? `${w.toLocaleString()} × ${h.toLocaleString()} px` : '원본 해상도';
  const ext = (url, kind) => kind === 'video' ? 'mp4' : (/\.(png|webp|avif)(?:[?#]|$)/i.test(url) ? url.match(/\.(png|webp|avif)/i)[1] : 'jpg');
  const imageIndex = value => { try { const n = Number(new URL(value).searchParams.get('img_index')); return Number.isFinite(n) && n > 0 ? n - 1 : 0; } catch { return 0; } };

  const collectPage = `async({page})=>page.evaluate(()=>{const a=[],add=(u,k='image',w=0,h=0,i=0)=>{u=String(u||'').replace(/\\u0026/g,'&').replace(/\\u002F/gi,'/').replace(/\\\//g,'/');if(/^(?:https?:)?\\/\\/(?:[^/]+\\.)?(?:cdninstagram|fbcdn|fbsbx)\\./i.test(u))a.push({url:u,kind:k,width:+w||0,height:+h||0,index:i})};const scan=t=>{for(const m of t.matchAll(/"video_url":"([^"]+)"/g))add(m[1],'video');for(const m of t.matchAll(/"display_url":"([^"]+)"/g))add(m[1]);};document.querySelectorAll('script').forEach(s=>scan(s.textContent||''));document.querySelectorAll('video').forEach(v=>add(v.currentSrc||v.src,'video',v.videoWidth,v.videoHeight));document.querySelectorAll('img').forEach(i=>add(i.currentSrc||i.src,'image',i.naturalWidth,i.naturalHeight));return a})`;

  const collectGraphql = `async({page})=>page.evaluate(async()=>{let s=location.pathname.split('/').filter(Boolean)[1],A='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_',n=0;for(let c of s)n=n*64+A.indexOf(c);let h=document.documentElement.innerHTML,t=(h.match(/id="__eqmc"[^>]*>.*?"l":"([^"]+)/)||h.match(/\["LSD",\[\],\{"token":"([^"]+)/)||[])[1];if(!t)return[];let r=await fetch('/api/graphql',{method:'POST',headers:{'X-FB-Friendly-Name':'PolarisLoggedOutDesktopWWWPostRootContentQuery','X-FB-LSD':t},body:new URLSearchParams({lsd:t,fb_api_caller_class:'RelayModern',fb_api_req_friendly_name:'PolarisLoggedOutDesktopWWWPostRootContentQuery',variables:JSON.stringify({media_id:String(n)}),doc_id:'27130156389949648'})}),p=await r.json(),m=p?.data?.xig_polaris_media?.if_not_gated_logged_out,o=[],a=(x,i)=>{x?.image_versions2?.candidates?.forEach(v=>o.push({url:v.url,width:v.width,height:v.height,index:i}));x?.video_versions?.forEach(v=>o.push({url:v.url,width:v.width,height:v.height,index:i,kind:'video'}))};(m?.carousel_media||[m]).forEach(a);return o})`;

  async function pasteLink() { try { const text = await navigator.clipboard.readText(); if (text) { input = text.trim(); copied = true; setTimeout(() => copied = false, 1200); } } catch {} }

  async function request(url, mode) {
    const target = mode === 'embed' ? `${url.replace(/\/?([?#].*)?$/,'')}/embed/` : url;
    const fn = mode === 'graphql' ? collectGraphql : collectPage;
    const response = await fetch(`https://api.microlink.io/?${new URLSearchParams({url:target,meta:'true',function:fn})}`);
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(payload?.message || `Microlink ${response.status}`);
    const out = [];
    const push = value => { const raw=value?.url||value?.src||value; const u=normalizeUrl(raw).trim(); if(!validUrl(u)) return; const kind=value?.kind || (/\.(mp4|m3u8)(?:[?#]|$)/i.test(u)?'video':'image'); out.push({url:u,kind,width:+value?.width||0,height:+value?.height||0,index:Number.isFinite(+value?.index)?+value.index:0}); };
    (Array.isArray(payload?.data?.function)?payload.data.function:[]).forEach(push);
    [payload?.data?.video,payload?.data?.videos,payload?.data?.image,payload?.data?.images].flat().filter(Boolean).forEach(push);
    const unique=new Map(); for(const x of out){const k=`${x.kind}|${x.index}|${x.url.split('?')[0]}`;const old=unique.get(k);if(!old||area(x)>area(old))unique.set(k,x);} return [...unique.values()];
  }

  async function extract() {
    error=''; status=''; media=[]; selected=0; stage=''; const value=input.trim(); const video=isVideoUrl(value);
    if(!isInstagramUrl(value)){error='Instagram 링크 형식이 아니에요.';stage='/p, /reel, /reels, /tv 링크를 사용해 주세요.';return;}
    loading=true; status=video?'릴스 원본을 확인하고 있어요':'사진 원본과 캐러셀을 확인하고 있어요'; stage=video?'공개 페이지 → GraphQL video_versions → 임베드':'공개 페이지 → GraphQL carousel_media';
    try {
      let found=await request(value,'page');
      if(video && !found.some(x=>x.kind==='video')){stage='GraphQL · 실제 video_versions';found=[...await request(value,'graphql'),...found];}
      if(!video){stage='GraphQL · image_versions2 / carousel_media';const gql=await request(value,'graphql');if(gql.length)found=[...gql,...found];}
      if(video && !found.some(x=>x.kind==='video')){stage='공개 임베드 재확인';found=[...await request(value,'embed'),...found];}
      if(!found.length || (video&&!found.some(x=>x.kind==='video'))) throw new Error('not-found');
      if(!video){
        const wanted=imageIndex(value); const indexed=found.filter(x=>x.kind==='image'&&x.index===wanted); const fallback=found.filter(x=>x.kind==='image'); const pool=indexed.length?indexed:fallback;
        const byIndex=new Map(); for(const x of pool){const old=byIndex.get(x.index);if(!old||area(x)>area(old))byIndex.set(x.index,x);} const ordered=[...byIndex.entries()].sort((a,b)=>a[0]-b[0]).map(x=>x[1]);
        media=ordered.length?ordered:found.filter(x=>x.kind==='image').sort((a,b)=>area(b)-area(a)); selected=Math.max(0,media.findIndex(x=>x.index===wanted));
      } else { media=found.filter(x=>x.kind==='video').sort((a,b)=>area(b)-area(a)).slice(0,8); }
      if(!media.length) throw new Error('not-found');
      status=video?`${media.length}개 동영상 원본 후보 확인`:`${media.length}개 사진 확인 · ${imageIndex(value)+1}번 이미지 우선 선택`;
      stage='✓ 원본 미디어 확인 완료';
    } catch { error=video?'릴스 동영상 원본을 찾지 못했어요.':'사진 원본을 찾지 못했어요.';stage='공개 게시물인지 확인하고 잠시 후 다시 시도해 주세요.'; }
    finally { loading=false; }
  }

  const current=()=>media[selected]||null;
  async function save(item,index=selected){if(!item?.url)return;status=`${item.kind==='video'?'동영상':'사진'} 저장 중`;try{const r=await fetch(item.url,{mode:'cors'});if(!r.ok)throw 0;const b=await r.blob(),h=URL.createObjectURL(b),a=document.createElement('a');a.href=h;a.download=`instagram-${String(index+1).padStart(2,'0')}-${Date.now()}.${ext(item.url,item.kind)}`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(h);status=`저장 완료 · ${resolution(item.width,item.height)}`;}catch{status='원본 주소를 새 탭에서 열었어요';window.open(item.url,'_blank','noopener,noreferrer');}}
  function openOriginal(){const item=current();if(item)window.open(item.url,'_blank','noopener,noreferrer');}
</script>

<svelte:head><meta name="apple-mobile-web-app-capable" content="yes"/><meta name="theme-color" content="#08080a"/><title>InstaSave · Instagram 공개 미디어 저장</title></svelte:head>

<main class="page"><div class="ambient a1"></div><div class="ambient a2"></div><section class="shell">
  <header class="topbar"><div class="brand"><div class="brand-mark">IS</div><div><b>InstaSave</b><small>PUBLIC MEDIA</small></div></div><div class="status-dot"><i></i> ONLINE</div></header>
  <section class="hero"><div class="eyebrow">01 · INSTAGRAM EXTRACTOR</div><h1>원본 사진을<br/><em>깔끔하게 저장하세요.</em></h1><p>게시물 링크 하나로 원본 이미지와 캐러셀을 찾아요.<br class="desktop"/> <strong>img_index=2</strong> 같은 링크도 해당 번호를 우선 선택합니다.</p></section>
  <section class="card"><div class="card-head"><span><b>1</b> Instagram 링크</span><button class="paste" type="button" on:click={pasteLink}>{copied?'붙여넣음 ✓':'붙여넣기'}</button></div><form on:submit|preventDefault={extract}><div class="input-row"><span class="link-icon">↗</span><input bind:value={input} type="url" inputmode="url" autocomplete="off" placeholder="instagram.com/p/..." aria-label="Instagram 링크"/>{#if input}<button class="clear" type="button" on:click={()=>input=''}>×</button>{/if}<button class="primary" type="submit" disabled={loading}>{loading?'찾는 중':'원본 찾기'} <b>→</b></button></div></form><div class="chips"><span>✓ 공개 게시물</span><span>✓ 캐러셀 지원</span><span>✓ 원본 해상도 우선</span></div></section>
  {#if loading}<div class="progress"><div class="spinner"></div><div><strong>{status}</strong><small>{stage}</small></div></div>{/if}
  {#if error}<div class="error"><b>!</b><div><strong>{error}</strong><span>{stage}</span></div><button type="button" on:click={extract}>다시 시도</button></div>{/if}
  {#if media.length}{@const item=current()}<article class="result"><div class="result-top"><div><span></span> {item.kind==='video'?'VIDEO':'PHOTO'} <b>{selected+1} / {media.length}</b></div><label>{item.kind==='video'?'ORIGINAL VIDEO':'ORIGINAL IMAGE'}</label></div><div class="preview">{#if item.kind==='video'}<video src={item.url} controls playsinline preload="metadata"></video>{:else}<img src={item.url} alt="Instagram 원본"/>{/if}<div class="resolution">{resolution(item.width,item.height)}</div></div><div class="result-body"><div><h2>{item.kind==='video'?'릴스 원본 동영상':'Instagram 원본 사진'}</h2><p>{item.kind==='video'?'실제 video_versions 스트림':'image_versions2 후보에서 선택된 원본'} · {item.index+1}번 미디어</p></div><div class="actions"><button class="secondary" on:click={openOriginal}>원본 열기</button><button class="download" on:click={()=>save(item)}>↓ <span>{item.kind==='video'?'동영상 저장':'사진 저장'}</span></button></div></div>{#if media.length>1}<div class="gallery"><div class="gallery-label">캐러셀 <b>{selected+1} / {media.length}</b></div><div class="thumbs">{#each media as candidate,index}<button type="button" class:active={index===selected} class="thumb" on:click={()=>selected=index} aria-label={`${index+1}번 미디어`}><img src={candidate.url} alt="" loading="lazy"/><span>{index+1}</span></button>{/each}</div></div>{/if}{#if status}<p class="result-status">{status}</p>{/if}</article>{/if}
  <footer><span>✦</span> 공개적으로 접근 가능한 Instagram 미디어만 처리합니다.</footer>
</section></main>

<style>
:global(*){box-sizing:border-box}:global(body){margin:0;background:#08080a;color:#f5f4f7;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}:global(button),:global(input){font:inherit}.page{min-height:100vh;overflow:hidden;position:relative;background:radial-gradient(circle at 20% 0%,#25202c 0,#0d0c11 34%,#08080a 72%)}.ambient{position:absolute;border-radius:50%;filter:blur(70px);opacity:.35;pointer-events:none}.a1{width:420px;height:420px;top:-240px;left:-130px;background:#7049a6}.a2{width:360px;height:360px;right:-180px;top:34%;background:#2f5b8c}.shell{width:min(860px,calc(100% - 32px));margin:auto;position:relative;padding:28px 0 34px}.topbar{display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px}.brand-mark{width:40px;height:40px;border:1px solid #4c4655;border-radius:12px;display:grid;place-items:center;font-size:12px;font-weight:800;letter-spacing:.08em;background:#141218}.brand b{display:block;font-size:15px}.brand small{display:block;color:#77717d;font-size:9px;letter-spacing:.15em;margin-top:2px}.status-dot{font-size:9px;color:#8f8994;letter-spacing:.12em}.status-dot i,.result-top span{display:inline-block;width:6px;height:6px;border-radius:50%;background:#79d59c;box-shadow:0 0 12px #79d59c;margin-right:6px}.hero{padding:72px 8px 40px}.eyebrow{font-size:10px;letter-spacing:.18em;color:#8f8498;margin-bottom:18px}.hero h1{font-size:clamp(42px,7vw,72px);line-height:.98;letter-spacing:-.055em;margin:0;font-weight:800}.hero em{font-style:normal;color:#a99ab6}.hero p{color:#89838e;line-height:1.75;margin:23px 0 0;font-size:14px}.hero strong{color:#bbb1c2;font-weight:600}.card,.result,.progress,.error{background:rgba(20,18,24,.82);border:1px solid #302c35;border-radius:22px;box-shadow:0 18px 60px rgba(0,0,0,.22)}.card{padding:18px}.card-head{display:flex;align-items:center;justify-content:space-between;color:#bdb6c2;font-size:12px;margin-bottom:13px}.card-head b{display:inline-grid;place-items:center;width:24px;height:24px;border-radius:8px;background:#2a2530;color:#fff;margin-right:8px}.paste,.secondary{background:#18161c;color:#a7a0aa;border:1px solid #38323d;border-radius:10px;padding:8px 11px;font-size:11px;cursor:pointer}.input-row{display:flex;align-items:center;gap:8px;background:#0c0b0f;border:1px solid #3a3540;border-radius:15px;padding:6px}.link-icon{color:#8f8795;padding-left:9px}.input-row input{flex:1;min-width:0;background:transparent;border:0;outline:0;color:#eee;padding:13px 4px;font-size:14px}.input-row input::placeholder{color:#57515c}.clear{border:0;background:none;color:#77717b;font-size:21px;cursor:pointer}.primary,.download{border:0;border-radius:11px;background:#f3eff5;color:#0d0c0f;padding:13px 16px;font-weight:750;cursor:pointer;white-space:nowrap}.primary:disabled{opacity:.55;cursor:wait}.primary b{margin-left:12px}.chips{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.chips span{font-size:10px;color:#77717e;background:#141219;border:1px solid #28242d;border-radius:99px;padding:7px 9px}.progress{display:flex;align-items:center;gap:13px;margin-top:14px;padding:14px 17px}.spinner{width:20px;height:20px;border:2px solid #38333c;border-top-color:#eee;border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.progress strong,.progress small{display:block}.progress strong{font-size:12px}.progress small{font-size:10px;color:#706a75;margin-top:4px}.error{display:flex;align-items:center;gap:12px;padding:14px;margin-top:14px}.error>b{width:30px;height:30px;border-radius:9px;background:#2b2023;color:#e8a5ac;display:grid;place-items:center}.error-copy{flex:1}.error strong,.error span{display:block}.error strong{font-size:12px}.error span{font-size:10px;color:#756f79;margin-top:4px}.error button{border:0;background:#28232b;color:#ddd6df;border-radius:9px;padding:8px 10px;font-size:10px;cursor:pointer}.result{margin-top:18px;overflow:hidden}.result-top{height:52px;display:flex;align-items:center;justify-content:space-between;padding:0 17px;color:#aaa3ae;font-size:10px;letter-spacing:.08em}.result-top b{color:#f1edf3;margin-left:5px}.result-top label{font-size:9px;color:#817887;border:1px solid #3a3440;border-radius:99px;padding:6px 8px}.preview{position:relative;background:#0b0a0d;min-height:260px;display:grid;place-items:center;overflow:hidden}.preview img,.preview video{display:block;width:100%;max-height:620px;object-fit:contain}.resolution{position:absolute;right:12px;bottom:12px;background:rgba(5,5,7,.75);backdrop-filter:blur(8px);border:1px solid #48414d;border-radius:8px;padding:6px 8px;font-size:9px;color:#d2ccd5}.result-body{display:flex;justify-content:space-between;gap:20px;padding:20px}.result-body h2{font-size:16px;margin:0}.result-body p{font-size:10px;color:#756f79;margin:7px 0 0}.actions{display:flex;gap:8px;align-items:center}.download{background:#e8dfea;color:#151117}.gallery{border-top:1px solid #2b2730;padding:14px 17px}.gallery-label{font-size:10px;color:#756f7d;margin-bottom:10px}.gallery-label b{color:#e7e1e9;margin-left:4px}.thumbs{display:flex;gap:8px;overflow-x:auto;padding-bottom:2px}.thumb{position:relative;flex:0 0 64px;height:64px;padding:0;border:1px solid #2d2931;border-radius:10px;overflow:hidden;background:#111;cursor:pointer}.thumb img{width:100%;height:100%;object-fit:cover}.thumb span{position:absolute;left:5px;top:5px;background:rgba(0,0,0,.7);color:#fff;border-radius:5px;font-size:8px;padding:3px 5px}.thumb.active{border:2px solid #eee}.result-status{margin:0;padding:0 17px 15px;color:#7e7782;font-size:10px}footer{text-align:center;color:#5e5963;font-size:10px;padding:24px 0 4px}footer span{margin-right:5px;color:#9a8da1}@media(max-width:600px){.shell{width:min(100% - 20px,860px);padding-top:18px}.hero{padding:54px 3px 30px}.hero h1{font-size:43px}.hero p{font-size:12px}.desktop{display:none}.card{padding:14px}.input-row{padding:5px}.primary{padding:12px 12px}.primary b{margin-left:5px}.result-body{display:block}.actions{margin-top:14px}.actions button{flex:1}.preview{min-height:230px}.status-dot{display:none}}
</style>